function check(bool $test,string $label):void{global $n;if(!$test)throw new RuntimeException('FAIL: '.$label);$n++;echo "PASS $label\n";}
function rejected(callable $fn,string $label):void{try{$fn();}catch(Throwable $e){if(!$e instanceof Problem&&!$e instanceof PDOException)throw $e;check(true,$label);return;}throw new RuntimeException('FAIL (accepted): '.$label);}
function png_logo(int $red,int $green,int $blue,int $width=1,int $height=1):string {
    $chunk=static fn(string $type,string $data):string=>pack('N',strlen($data)).$type.$data.pack('N',crc32($type.$data));
    $row="\0".str_repeat(chr($red).chr($green).chr($blue),$width);
    $png="\x89PNG\r\n\x1a\n".$chunk('IHDR',pack('NNCCCCC',$width,$height,8,2,0,0,0)).$chunk('IDAT',gzcompress(str_repeat($row,$height))).$chunk('IEND','');
    return 'data:image/png;base64,'.base64_encode($png);
}
